import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.26/x-thread-en.md","filePath":"announcements/v1.26/x-thread-en.md"}'),r={name:"announcements/v1.26/x-thread-en.md"};function i(c,e,n,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<p>1/ kiwa v1.26 is out — Database depth milestone. After v1.14 landed <code>@kiwa-test/orm</code> v0.8 with the Drizzle / Prisma / Kysely × Postgres / MySQL / SQLite 3 × 3 provider-backend matrix + testcontainers real driver, v1.26 stacks <strong>8 axis advanced production db semantics</strong> on top (replication / cdc / logical-replication / mvcc / rls / connection-pool / partitioning / vector-store). <code>@kiwa-test/orm</code> v0.8.0 → v0.9.0 minor bump. 288 dialect entries + 72 row fidelity grid + 222 new semantics tests + 3 dogfood app + tutorial 47-49.</p><p>2/ Why 8 axis coverage? A 2-3 axis pilot has 3 failure modes — cross-backend semantics drift (Postgres wal2json vs MySQL row-based binlog silently disagree), terminal state drift (revoked / exhausted / closed-window guards only tested on pilot), provider overlay drift (Prisma / Drizzle / Kysely translate to the same neutral event only if wired for every axis). The 4-rule SSOT (<code>docs/concepts/db-advanced-testing.md</code>) — 1 axis = 1 file / 1 axis = 5 helpers / neutral events over dialect / overlay-for-translation-only — is the smallest set that makes kiwa db suites comparable across packages, milestones, and forks.</p><p>3/ v1.26-1 orm v0.9 8 axis semantics — 40 helper (8 axis × 5 helper each) in <code>packages/orm/src/semantics/*</code> pure state machine, no adapter / no network. <code>createReplicationSession</code> + <code>primaryWrite</code> / <code>markReplicaLagged</code> / <code>startFailover</code> / <code>promoteReplica</code> for streaming replication + read replica lag + failover + promoted-replica. Same shape for cdc / logical-replication / mvcc / rls / connection-pool / partitioning / vector-store.</p><p>4/ 3 provider × 3 backend × 32 neutral event = 288 dialect entries. <code>collectFidelityCoverage({ providers, backends })</code> collects a 3 × 3 × 8 = 72 row fidelity grid for release-gate wiring. 222 new behavior tests bring <code>semantics/</code> statement coverage to 99.54 %, branch 95.61 %, function 100 %. SQLite falls back to neutral event names for server-only axes so downstream fanout tests still fire.</p><p>5/ v1.26-2 dogfood-postgres-cdc-outbox-app — Postgres 16 logical replication + Debezium-style outbox pattern + Redis Streams consumer + at-least-once + idempotent + backpressure. 5-op adapter (mock backed by orm CDC + logical-replication + replication + connection-pool sessions, real gated by <code>POSTGRES_BOOTSTRAP</code>). 28 vitest + 7 axis release gate PASS.</p><p>6/ v1.26-3 dogfood-mysql-rls-tenant-app — Nuxt 3 + Prisma + MySQL 8 row-level security + tenant_id auto-injection + cross-tenant refuse + <code>bypass_rls</code> role window + tamper-evident chain-hash audit log (<code>sha256(prev || entryJson)</code>). 5-op adapter (mock backed by orm RLS session, real gated by <code>MYSQL_KEY</code>). 34 vitest + 7 axis release gate PASS.</p><p>7/ v1.26-4 dogfood-vector-search-app — Postgres 16 pgvector IVFFlat + HNSW index + cosine/L2 distance + hybrid semantic + BM25 keyword search + FNV-folded cacheKey embedding cache + on-demand re-index. 5-op adapter (mock backed by orm vector-store session, real gated by <code>VECTOR_KEY</code>). 41 vitest + 7 axis release gate PASS.</p><p>8/ v1.26-5 docs — tutorial 47 (Postgres CDC + outbox) + tutorial 48 (MySQL RLS + tenant) + tutorial 49 (pgvector + hybrid search) + concept doc <code>db-advanced-testing.md</code> 8 axis SSOT + migration <code>v1.25 → v1.26</code> (additive-only) + snippet validation <code>docs-tutorial-v1.26.test.ts</code> (32 test) re-runs every code snippet against the real <code>@kiwa-test/orm</code> v0.9 API.</p><p>9/ v1.26-6 publish — <code>@kiwa-test/orm</code> v0.8.0 → v0.9.0 minor bump goes to npm. plugin.json 1.26.0 + 39 new db-focused keywords + Roadmap ✅ v1.26 row + announcement 4 file + release-smoke <code>v1-26-publish.test.ts</code> (7 axis invariant) + docs-e2e <code>V1_26_PAGES</code> (5 pages) + release script filter verified. gh-pages published via <code>/docs-publish-kiwa</code>. Roadmap: <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 → v1.20 → v1.21 → v1.22 → v1.23 → v1.24 → v1.25 → v1.26: 16 milestones in a row.</p>',9)])])}const g=o(r,[["render",i]]);export{m as __pageData,g as default};
